  "rxiob": "Vor jedem Schritt fragen Sie: \"Was hat mein Gegner nur bedroht? Nach diesem Schritt, welche meiner Stücke ist unverteidigt?\"",
  "1iwpe2z": "Jedes Runde, schauen Sie sich zuerst auf Überprüfungen, Fangen und Bedrohungen an: Der Gewinner-Schlag ist normalerweise da.",
