  "1fs9wy0": "Wenn Sie im Material voran gehen: Teile austauschen, bringen Sie Ihren König auf und drücken Sie einen verpassten Pfeil. Schnell nicht: Überprüfen Sie jeden Schritt, damit Sie nicht steilen.",
