  "1krmn15": "Einheit: {0}",
  "268emb": "Ich brauche mindestens 2 Spiele, die von Stockfish analysiert wurden, um genau zu kommentieren (sie haben {0}). Spielen Sie ein paar weitere Spiele oder Druck",
