  "1t7sota": "Halten Sie diese guten Gewohnheiten auf und konzentrieren Sie sich auf {0}.",
  "sxkbb2": "Von {0} zu {1} Elo: (1) 10–15 Minuten taktische Puzzles jeden Tag, (2) regelmäßig überprüfen Sie den Notebook Fehler, (3) spielen Sie länger Spiele (10 Minuten oder mehr) gegen {2} und überprüfen Sie jede Verlust, (4) beheben Sie Ihre größte aktuelle Schwäche:",
  "1763pgg": "Endgame: {0} Bewegungen analysiert, {1} große Fehler; {2} Gewinnspiele nicht gewonnen. {3}",
  "1gtjhew": "Sie verpassen {0} Taktik und {1} Check-Friends, und verlassen einen Stück zu gewinnen {2} Mal. {3}",
  "1dw79cf": "Es enthält schriftliche Artikel, {0} Öffnungen und Endgame-Positionen aus der Bibliothek und die 20 Lern-Einheiten. Der Coach überprüft diese Bibliothek, bevor er erklärt.",
  "8o72bq": "{0} Ich werde in Grundmodus antworten:",
