  "cmf65k": "Der weiße König steht bereits auf der Schlüsselstreck e6. Förderung der Paune!",
  "wi5eu5": "Die Außenverkehrsstraße verläuft",
  "1l4ncmw": "Der A-Pahn ist ein Außenpassungspaun: Drücken Sie es, um den schwarzen König wegzuziehen, dann spricht der weiße König den anderen Paun. Promotion zu machen!",
  "yzv26c": "Drei-Paure Durchbruch",
  "151pyxt": "Drei Paune gegen drei, Könige weit weg. Durchbrechen mit b6! und dann c6!: ein weißes Paun wird durch und fördert.",
  "qnqv7l": "Die Steine Pawn",
  "1dijxk0": "König und A-Pahn gegen einen schwarzen König bereits im Jahr a8. Was ist das Ergebnis?",
  "jucz5o": "Sobald der schwarze König den Winkel erreicht, kann der Staubspiegel nicht fördern: es ist ein Zeichnen oder Stalemate.",
