  "1p8wkbt": "Die Position Lucena (der Angreifer gewinnt): Was ist die berühmte Technik genannt?",
  "wt9bn": "\"Ein Brücken bauen\" - mit dem Dach, um den König vor Schecken zu schützen",
  "1xfmuyn": "Handelsröcke",
  "de2frr": "Lucena Position: Der weiße König ist auf d8 vor dem Paun. Bringen Sie den Dach auf den 4. Platz, um \"eine Brücke zu bauen\", dann fördern Sie! Der Computer spielt schwarz.",
  "ok3r28": "Abschneiden Sie den König",
  "60x3bw": "Warum verwenden Sie den Dach, um den Feind King entlang einer Datei oder einer Reihe zu \"schneiden\"?",
  "1ui0cjd": "Der Feindkrieg kann nicht in die Zeit zurückkehren, um den Pferd zu stoppen",
  "ww32hs": "zum Handel mit Röcken",
  "x3268c": "Um dein eigenes König sicher zu halten",
  "19y4dfu": "Der falsche Bischof",
  "1lyiebm": "König, Bischof und H-Pahn, aber der Bischof kontrolliert nicht die Promotationsplatz h8 und der schwarze König ist im Winkel. Was ist das Ergebnis?",
  "1y0ib49": "Rook Endgame Review",
  "17c069s": "Berechnung & Absolventen",
  "1oaiv9p": "Forcing Moves, der Blunder-Check und der endgültige Prüfung",
  "v4phrp": "Forcing Bewegungen",
  "1d38kk9": "Wenn Sie berechnen, in welcher Reihenfolge sollten Sie zuerst auf Bewegungen betrachten?",
  "28ctmc": "Überprüfen – Fangen – Bedrohungen",
  "jao6z3": "Pawn Moves – Entwicklung – Castling",
  "xib0or": "König – Queen – Röck bewegt",
  "16r9n51": "Bevor Sie einen Stück berühren, was ist der letzte Check?",
  "1fue8p6": "Kann mein Gegner nach diesem Schritt etwas überprüfen, fangen oder bedrohen?",
  "1i9uwoc": "schnell bewegen",
  "1q4l3xi": "Schau mal auf meine eigenen Stücke",
  "3vfpc2": "Beginnen Sie mit einem zwingenden Schritt! Matte in 2",
  "ai8bft": "Opfer zu gewinnen",
